from pathlib import Path
from html.parser import HTMLParser
out=Path('/app/output')
class P(HTMLParser):
    def __init__(self): super().__init__(); self.hrefs=[]; self.scripts=[]; self.links=[]
    def handle_starttag(self, tag, attrs):
        d=dict(attrs)
        if tag=='a' and 'href' in d: self.hrefs.append(d['href'])
        if tag=='script' and 'src' in d: self.scripts.append(d['src'])
        if tag=='link' and 'href' in d: self.links.append(d['href'])
for html in ['index.html','packages.html','car-rental.html','attractions.html']:
    p=P(); p.feed((out/html).read_text())
    missing=[]
    for ref in p.hrefs+p.scripts+p.links:
        if ref.startswith(('#','http')) or ref in [''] or ref.startswith('mailto:'): continue
        if not (out/ref).exists(): missing.append(ref)
    print(html, 'missing refs:', missing or 'none')
